BOT_AVATAR_B64 = ""

def clean_html(s: str) -> str:
    """
    Dedents, strips blank lines, and collapses all newlines and multiple spaces
    into a single line so Streamlit / CommonMark will NEVER parse it as a markdown code block.
    """
    if not s:
        return ""
    s = textwrap.dedent(s).strip()
    s = re.sub(r'>\s+<', '><', s)
    s = re.sub(r'\s+', ' ', s)
    return s.strip()

def _format_time(dt_val=None) -> str:
    """Formats current or provided timestamp to HH:MM AM/PM."""
    if not dt_val:
        return datetime.now().strftime("%I:%M %p")
    try:
        if isinstance(dt_val, str):
            clean_str = dt_val.replace("T", " ")[:19]
            dt = datetime.strptime(clean_str, "%Y-%m-%d %H:%M:%S")
            return dt.strftime("%I:%M %p")
    except Exception:
        pass
    return str(dt_val)[:16]

def _render_understanding_card(meta: dict, lang: str = "en") -> str:
    """Renders 3-column Category / Location / Summary card matching reference design."""
    tid = html.escape(str(meta.get("ticket_id", "GRV-1042")))
    cat_val = meta.get("category") or "Water Supply"
    cat = html.escape(label("categories", cat_val, lang) if cat_val else cat_val)
    loc = html.escape(str(meta.get("location") or meta.get("area") or "Berhampur, Ganjam"))
    summary = html.escape(str(meta.get("summary") or "Water supply not coming for 2 days"))
    dept_val = meta.get("department", "Water Resources Department")
    dept = html.escape(label("departments", dept_val, lang))
    conf_val = meta.get("confidence")
    conf_pct = round(float(conf_val if conf_val is not None else 0.95) * 100)

    u_drop_icon = icon("droplet", size=20, color="#2B7FFF")
    u_pin_icon = icon("map_pin", size=20, color="#8E2A8B")
    u_doc_icon = icon("file_text", size=20, color="#8E2A8B")

    u_card = f"""
    <div class="understanding-summary-card">
        <div class="u-col-item">
            <div style="flex-shrink: 0; display: flex; align-items: center;">{u_drop_icon}</div>
            <div>
                <div class="u-col-label">Category</div>
                <div class="u-col-val">{cat}</div>
            </div>
        </div>
        <div class="u-col-item">
            <div style="flex-shrink: 0; display: flex; align-items: center;">{u_pin_icon}</div>
            <div>
                <div class="u-col-label">Location</div>
                <div class="u-col-val">{loc}</div>
            </div>
        </div>
        <div class="u-col-item">
            <div style="flex-shrink: 0; display: flex; align-items: center;">{u_doc_icon}</div>
            <div>
                <div class="u-col-label">Summary</div>
                <div class="u-col-val">{summary}</div>
            </div>
        </div>
    </div>
    <div class="routing-normal-line">
        I will forward this to the {dept} with confidence score of {conf_pct}%.
    </div>
    <div style="font-size: 14px; color: var(--text); display: flex; align-items: center; gap: 6px; margin-top: 4px;">
        <span>Your Tracking ID is:</span>
        <span class="tracking-pill-chip">{tid}</span>
    </div>
    """
    return clean_html(u_card)

def _render_stepper_card(status: str = "Assigned", history: list = None, lang: str = "en") -> str:
    """Renders Complaint Status stepper matching reference visual progress line."""
    steps = ["Submitted", "Assigned", "In Progress", "Resolved"]
    stat_clean = (status or "Assigned").strip()

    if stat_clean.lower() == "resolved":
        curr_idx = 3
        fill_width = "75%"
    elif stat_clean.lower() in ["in progress", "reopened"]:
        curr_idx = 2
        fill_width = "50%"
    elif stat_clean.lower() == "assigned":
        curr_idx = 1
        fill_width = "25%"
    else:
        curr_idx = 0
        fill_width = "0%"

    times = {
        "Submitted": "10:24 AM",
        "Assigned": "11:10 AM" if curr_idx >= 1 else ""
    }
    if history and isinstance(history, list):
        for h in history:
            s_name = h.get("status")
            t_raw = h.get("created_at")
            if s_name and t_raw:
                times[s_name] = _format_time(t_raw)

    items_html = []
    for idx, s_name in enumerate(steps):
        if idx < curr_idx:
            c_cls = "done"
            inner = "✓"
        elif idx == curr_idx:
            c_cls = "active"
            inner = '<span class="inner-dot"></span>'
        else:
            c_cls = "pending"
            inner = "⚙" if s_name == "In Progress" else "✓"

        t_str = times.get(s_name, "")
        t_html = f'<div class="stepper-time">({t_str})</div>' if t_str else ""
        s_lbl = html.escape(label("statuses", s_name, lang) or s_name)

        items_html.append(f"""
        <div class="stepper-node">
            <div class="stepper-circle {c_cls}">{inner}</div>
            <div class="stepper-label">{s_lbl}</div>
            {t_html}
        </div>
        """)

    stepper_card = f"""
    <div class="stepper-progress-card">
        <div class="stepper-card-title">Complaint Status</div>
        <div class="stepper-track-wrap">
            <div class="stepper-base-line"></div>
            <div class="stepper-fill-line" style="width: {fill_width};"></div>
            <div class="stepper-nodes-flex">
                {"".join(items_html)}
            </div>
        </div>
    </div>
    """
    return clean_html(stepper_card)

